    public static int TextAppendCp(emon.Port.Cells text, int cp) {
        // Append one Unicode scalar value; answer the index it went to.
        // Anything that is not a scalar value (negative, past U+10FFFF, a
        // surrogate) is stored as U+FFFD, so the arena only ever holds
        // what SPEC 3.6 says it holds.
        if (cp < 0) {
            return emon.Port.CellsPush(text, 65533);
        }
        if (cp > 1114111) {
            return emon.Port.CellsPush(text, 65533);
        }
        if ((cp >= 55296) && (cp <= 57343)) {
            return emon.Port.CellsPush(text, 65533);
        }
        return emon.Port.CellsPush(text, cp);
    }
    public static int TextAppendUtf8(emon.Port.Cells text, byte[] b, int from, int to) {
        // Decode b[from, to) as UTF-8 onto the text arena; answer the number
        // of code points appended. Invalid input becomes U+FFFD (SPEC 4.3:
        // 'invalid input decodes to U+FFFD at the source'), ONE per maximal
        // invalid subpart: a stray continuation byte, a bad lead, or a
        // sequence cut short is a single replacement, and decoding resumes
        // at the first byte that was not part of it.
        int i = from;
        int k = 0;
        int c = 0;
        int cp = 0;
        int need = 0;
        int lo = 128;
        int hi = 191;
        int ok = 1;
        int x = 0;
        while (i < to) {
            c = emon.Port.BlobU8(b, i);
            i += 1;
            need = 0;
            lo = 128;
            hi = 191;
            ok = 1;
            cp = c;
            if (c >= 128) {
                ok = 0;
                if ((c >= 194) && (c <= 223)) {
                    need = 1;
                    cp = c & 31;
                    ok = 1;
                }
                if ((c >= 224) && (c <= 239)) {
                    need = 2;
                    cp = c & 15;
                    ok = 1;
                    if (c == 224) {
                        lo = 160;
                    }
                    if (c == 237) {
                        hi = 159;
                    }
                }
                if ((c >= 240) && (c <= 244)) {
                    need = 3;
                    cp = c & 7;
                    ok = 1;
                    if (c == 240) {
                        lo = 144;
                    }
                    if (c == 244) {
                        hi = 143;
                    }
                }
            }
            while ((ok == 1) && (need > 0)) {
                if (i < to) {
                    x = emon.Port.BlobU8(b, i);
                    if ((x >= lo) && (x <= hi)) {
                        cp = (cp * 64) + (x & 63);
                        i += 1;
                        need -= 1;
                        lo = 128;
                        hi = 191;
                    } else {
                        ok = 0;
                    }
                } else {
                    ok = 0;
                }
            }
            if (ok == 0) {
                cp = 65533;
            }
            TextAppendCp(text, cp);
            k += 1;
        }
        return k;
    }
    public static int NodeAddRegion(emon.Port.Cells nodes, emon.Port.Cells regions, int n, int page, int x0, int y0, int x1, int y1) {
        // Append a region to the node's chain (in the order added: a node
        // spanning pages has one region per page, in page order) and answer
        // the region's index.
        int r = emon.Port.CellsLen(regions) / 6;
        int cnt = Nget(nodes, n, 10);
        int t = Nget(nodes, n, 9);
        emon.Port.CellsPush(regions, page);
        emon.Port.CellsPush(regions, x0);
        emon.Port.CellsPush(regions, y0);
        emon.Port.CellsPush(regions, x1);
        emon.Port.CellsPush(regions, y1);
        emon.Port.CellsPush(regions, -1);
        if (cnt == 0) {
            Nput(nodes, n, 9, r);
        } else {
            while (emon.Port.CellsAt(regions, (t * 6) + 5) >= 0) {
                t = emon.Port.CellsAt(regions, (t * 6) + 5);
            }
            emon.Port.CellsSet(regions, (t * 6) + 5, r);
        }
        Nput(nodes, n, 10, cnt + 1);
        return r;
    }
