    public static int AttrFind(emon.Port.Cells attrs, int head, int key) {
        // The first attribute with `key` in the chain from `head`, or -1.
        int a = head;
        while (a >= 0) {
            if (Aget(attrs, a, 0) == key) {
                return a;
            }
            a = Aget(attrs, a, 4);
        }
        return -1;
    }
    public static int AttrFindNext(emon.Port.Cells attrs, int a, int key) {
        // The next attribute with `key` AFTER a (a key may repeat: a
        // figure's `labels`, a furniture's `pages`), or -1.
        int nx = Aget(attrs, a, 4);
        return AttrFind(attrs, nx, key);
    }
    public static int NodeAttr(emon.Port.Cells nodes, emon.Port.Cells attrs, int n, int key) {
        // The node's first attribute with `key`, or -1.
        return AttrFind(attrs, Nget(nodes, n, 6), key);
    }
    public static int NodeAttrIntOr(emon.Port.Cells nodes, emon.Port.Cells attrs, int n, int key, int dflt) {
        // An int, bool or node attribute's value, or `dflt` when absent.
        int a = AttrFind(attrs, Nget(nodes, n, 6), key);
        if (a < 0) {
            return dflt;
        }
        return Aget(attrs, a, 2);
    }
    internal static int AttrPut(emon.Port.Cells nodes, emon.Port.Cells attrs, int n, int key, int vkind, int value, int ln, int replace) {
        // Set (replace = 1: overwrite the first attribute with the key, if
        // there is one) or add (replace = 0: always append) an attribute.
        int head = Nget(nodes, n, 6);
        int found = AttrFind(attrs, head, key);
        int a = emon.Port.CellsLen(attrs) / 5;
        int t = head;
        if ((replace == 1) && (found >= 0)) {
            emon.Port.CellsSet(attrs, (found * 5) + 1, vkind);
            emon.Port.CellsSet(attrs, (found * 5) + 2, value);
            emon.Port.CellsSet(attrs, (found * 5) + 3, ln);
            return found;
        }
        emon.Port.CellsPush(attrs, key);
        emon.Port.CellsPush(attrs, vkind);
        emon.Port.CellsPush(attrs, value);
        emon.Port.CellsPush(attrs, ln);
        emon.Port.CellsPush(attrs, -1);
        if (head < 0) {
            Nput(nodes, n, 6, a);
        } else {
            while (emon.Port.CellsAt(attrs, (t * 5) + 4) >= 0) {
                t = emon.Port.CellsAt(attrs, (t * 5) + 4);
            }
            emon.Port.CellsSet(attrs, (t * 5) + 4, a);
        }
        return a;
    }
