    public static int PageNew(emon.Port.Cells pages, int number, int w, int h, int rot, int kind) {
        // Append a page-table row and answer its index. A new row has no
        // label, no health and no resolution.
        int p = emon.Port.CellsLen(pages) / 16;
        int i = 0;
        emon.Port.CellsPush(pages, number);
        emon.Port.CellsPush(pages, -1);
        emon.Port.CellsPush(pages, 0);
        emon.Port.CellsPush(pages, w);
        emon.Port.CellsPush(pages, h);
        emon.Port.CellsPush(pages, rot);
        emon.Port.CellsPush(pages, kind);
        emon.Port.CellsPush(pages, -1);
        emon.Port.CellsPush(pages, 0);
        emon.Port.CellsPush(pages, 0);
        emon.Port.CellsPush(pages, 0);
        while (i < 5) {
            emon.Port.CellsPush(pages, 0);
            i += 1;
        }
        return p;
    }
