    internal static int McFail(emon.Port.Cells st, int code, int at) {
        emon.Port.CellsSet(st, 0, at);
        return code;
    }
    internal static int McLinkOk(int v, int n) {
        // 1 when v is -1 or an index below n.
        if (v < -1) {
            return 0;
        }
        if (v >= n) {
            return 0;
        }
        return 1;
    }
    internal static int McRunOk(int start, int ln, int tl) {
        // 1 for an absent run (start -1, ln 0) or one inside [0, tl).
        if (start == -1) {
            if (ln == 0) {
                return 1;
            }
            return 0;
        }
        if (start < 0) {
            return 0;
        }
        if (ln < 0) {
            return 0;
        }
        if (start > tl) {
            return 0;
        }
        if (ln > (tl - start)) {
            return 0;
        }
        return 1;
    }
    internal static int McCheckNode(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, int n, int nn) {
        // One node's own fields. 0 or an `mc` code.
        int kind = Nget(nodes, n, 0);
        int cnt = Nget(nodes, n, 10);
        int conf = Nget(nodes, n, 12);
        int a = Nget(nodes, n, 6);
        int r = Nget(nodes, n, 9);
        int steps = 0;
        int na = emon.Port.CellsLen(attrs) / 5;
        int nr = emon.Port.CellsLen(regions) / 6;
        int tl = emon.Port.CellsLen(text);
        if ((kind < 1) || (kind > 26)) {
            return McBadKind();
        }
        if (McLinkOk(Nget(nodes, n, 1), nn) == 0) {
            return McBadLink();
        }
        if (McLinkOk(Nget(nodes, n, 2), nn) == 0) {
            return McBadLink();
        }
        if (McLinkOk(Nget(nodes, n, 3), nn) == 0) {
            return McBadLink();
        }
        if (McLinkOk(Nget(nodes, n, 4), nn) == 0) {
            return McBadLink();
        }
        if (McLinkOk(Nget(nodes, n, 5), nn) == 0) {
            return McBadLink();
        }
        if (McRunOk(Nget(nodes, n, 7), Nget(nodes, n, 8), tl) == 0) {
            return McBadText();
        }
        if ((conf < -1) || (conf > 1000)) {
            return McBadConf();
        }
        while (a >= 0) {
            if (a >= na) {
                return McBadAttr();
            }
            if (steps > na) {
                return McBadAttr();
            }
            steps += 1;
            if (Aget(attrs, a, 1) == 1) {
                if (McRunOk(Aget(attrs, a, 2), Aget(attrs, a, 3), tl) == 0) {
                    return McBadAttr();
                }
            }
            if (McLinkOk(Aget(attrs, a, 4), na) == 0) {
                return McBadAttr();
            }
            if ((Aget(attrs, a, 1) < 0) || (Aget(attrs, a, 1) > 3)) {
                return McBadAttr();
            }
            a = Aget(attrs, a, 4);
        }
        steps = 0;
        while (r >= 0) {
            if (r >= nr) {
                return McBadRegion();
            }
            if (steps > nr) {
                return McBadRegion();
            }
            steps += 1;
            if (McLinkOk(Rget(regions, r, 5), nr) == 0) {
                return McBadRegion();
            }
            r = Rget(regions, r, 5);
        }
        if (steps != cnt) {
            return McBadRegion();
        }
        return 0;
    }
    internal static int McCheckChildren(emon.Port.Cells nodes, int n, int nn) {
        // The child chain of n: every child points back at n, prev links
        // agree, `last-child` is the end of the chain. Answers the number of
        // children, or -1 when the chain is wrong.
        int c = Nget(nodes, n, 2);
        int prev = -1;
        int k = 0;
        while (c >= 0) {
            if (k > nn) {
                return -1;
            }
            if (Nget(nodes, c, 1) != n) {
                return -1;
            }
            if (Nget(nodes, c, 5) != prev) {
                return -1;
            }
            k += 1;
            prev = c;
            c = Nget(nodes, c, 4);
        }
        if (Nget(nodes, n, 3) != prev) {
            return -1;
        }
        return k;
    }
    internal static int McCheckOrder(emon.Port.Cells nodes, int nn, emon.Port.Cells st) {
        // Pre-order ids: walking each tree in pre-order, from its root,
        // visits the indices consecutively, and the trees follow each other
        // in index order. So an id is the node's position in document
        // order (SPEC 3.3).
        int i = 0;
        int expect = 0;
        int cur = 0;
        while (i < nn) {
            if (Nget(nodes, i, 1) == -1) {
                if (i != expect) {
                    return McFail(st, McNotPreorder(), i);
                }
                cur = i;
                while (cur >= 0) {
                    if (cur != expect) {
                        return McFail(st, McNotPreorder(), cur);
                    }
                    expect += 1;
                    if (Nget(nodes, cur, 2) >= 0) {
                        cur = Nget(nodes, cur, 2);
                    } else {
                        while ((cur >= 0) && (cur != i) && (Nget(nodes, cur, 4) < 0)) {
                            cur = Nget(nodes, cur, 1);
                        }
                        if (cur == i) {
                            cur = -1;
                        } else if (cur >= 0) {
                            cur = Nget(nodes, cur, 4);
                        }
                    }
                }
            }
            i += 1;
        }
        if (expect != nn) {
            return McFail(st, McNotPreorder(), expect);
        }
        return 0;
    }
    public static int ModelCheck(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout, emon.Port.Cells st) {
        int nn = emon.Port.CellsLen(nodes) / 16;
        int nlay = emon.Port.CellsLen(layout) / 8;
        int j = 0;
        int i = 0;
        int rc = 0;
        int kids = 0;
        int total = 0;
        int nonroot = 0;
        int tl = emon.Port.CellsLen(text);
        emon.Port.CellsDrop(st, 0);
        emon.Port.CellsPush(st, 0);
        if ((emon.Port.CellsLen(nodes) % 16) != 0) {
            return McFail(st, McBadStride(), 0);
        }
        if ((emon.Port.CellsLen(attrs) % 5) != 0) {
            return McFail(st, McBadStride(), 0);
        }
        if ((emon.Port.CellsLen(regions) % 6) != 0) {
            return McFail(st, McBadStride(), 0);
        }
        if ((emon.Port.CellsLen(pages) % 16) != 0) {
            return McFail(st, McBadStride(), 0);
        }
        if ((emon.Port.CellsLen(ledger) % 10) != 0) {
            return McFail(st, McBadStride(), 0);
        }
        if ((emon.Port.CellsLen(layout) % 8) != 0) {
            return McFail(st, McBadStride(), 0);
        }
        if (nn < 1) {
            return McFail(st, McNoRoot(), 0);
        }
        if (Nget(nodes, 0, 0) != NkDocument()) {
            return McFail(st, McNoRoot(), 0);
        }
        if (Nget(nodes, 0, 1) != -1) {
            return McFail(st, McNoRoot(), 0);
        }
        while (i < nn) {
            rc = McCheckNode(nodes, attrs, regions, text, i, nn);
            if (rc != 0) {
                return McFail(st, rc, i);
            }
            i += 1;
        }
        i = 0;
        while (i < nn) {
            kids = McCheckChildren(nodes, i, nn);
            if (kids < 0) {
                return McFail(st, McBadTree(), i);
            }
            total += kids;
            if (Nget(nodes, i, 1) >= 0) {
                nonroot += 1;
            }
            i += 1;
        }
        if (total != nonroot) {
            return McFail(st, McBadTree(), 0);
        }
        rc = McCheckOrder(nodes, nn, st);
        if (rc != 0) {
            return rc;
        }
        i = 0;
        while (i < (emon.Port.CellsLen(pages) / 16)) {
            if (McRunOk(Pget(pages, i, 1), Pget(pages, i, 2), tl) == 0) {
                return McFail(st, McBadPage(), i);
            }
            i += 1;
        }
        i = 0;
        while (i < (emon.Port.CellsLen(ledger) / 10)) {
            if (McRunOk(Lget(ledger, i, 6), Lget(ledger, i, 7), tl) == 0) {
                return McFail(st, McBadLedger(), i);
            }
            if ((Lget(ledger, i, 8) < -1) || (Lget(ledger, i, 8) > 1000)) {
                return McFail(st, McBadLedger(), i);
            }
            i += 1;
        }
        i = 0;
        while (i < (emon.Port.CellsLen(pages) / 16)) {
            if (Pget(pages, i, 12) < 0) {
                return McFail(st, McBadLayout(), i);
            }
            if (Pget(pages, i, 12) > 0) {
                if (Pget(pages, i, 11) < 0) {
                    return McFail(st, McBadLayout(), i);
                }
                if (Pget(pages, i, 11) > (nlay - Pget(pages, i, 12))) {
                    return McFail(st, McBadLayout(), i);
                }
                j = 0;
                while (j < Pget(pages, i, 12)) {
                    if (Yget(layout, Pget(pages, i, 11) + j, 0) != Pget(pages, i, 0)) {
                        return McFail(st, McBadLayout(), i);
                    }
                    if ((Yget(layout, Pget(pages, i, 11) + j, 3) != RlBody()) && (Yget(layout, Pget(pages, i, 11) + j, 3) != RlMargin()) && (Yget(layout, Pget(pages, i, 11) + j, 3) != RlSidebar())) {
                        return McFail(st, McBadLayout(), i);
                    }
                    j += 1;
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static long MhFold(long h, emon.Port.Cells c) {
        // FNV-1a over the cells of one arena, each as a 32-bit pattern, then
        // the arena's length -- so two arenas that differ only in where one
        // ends and the next begins do not collide.
        int i = 0;
        long acc = h;
        while (i < emon.Port.CellsLen(c)) {
            acc = unchecked((acc ^ ((long) emon.Port.CellsAt(c, i))) * 1099511628211);
            i += 1;
        }
        return unchecked((acc ^ ((long) emon.Port.CellsLen(c))) * 1099511628211);
    }
    public static long ModelHash(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout) {
        // A 64-bit fingerprint of the whole Model: the gate's proof that four
        // targets built the same seven arenas. FNV-1a, offset basis
        // 14695981039346656037 (as a signed value) and prime 1099511628211.
        long h = -3750763034362895579;
        h = MhFold(h, nodes);
        h = MhFold(h, attrs);
        h = MhFold(h, regions);
        h = MhFold(h, text);
        h = MhFold(h, pages);
        h = MhFold(h, ledger);
        h = MhFold(h, layout);
        return h;
    }
    internal static int Xget(emon.Port.Cells assets, int a, int f) {
        return emon.Port.CellsAt(assets, (a * 24) + f);
    }
    internal static int Xset(emon.Port.Cells assets, int a, int f, int v) {
        emon.Port.CellsSet(assets, (a * 24) + f, v);
        return 0;
    }
    public static int AssetAdd(emon.Port.Cells assets, int mtype, int origin, int afrom, int @object, int bstart, int blen, int w, int h, int dpi, int flags) {
        // Append an asset (no uses yet, the hash zero) and answer its id. `object` is -1 for none, `dpi` 0.
        int id = emon.Port.CellsLen(assets) / 24;
        int i = 0;
        emon.Port.CellsPush(assets, mtype);
        emon.Port.CellsPush(assets, origin);
        emon.Port.CellsPush(assets, afrom);
        emon.Port.CellsPush(assets, @object);
        emon.Port.CellsPush(assets, bstart);
        emon.Port.CellsPush(assets, blen);
        while (i < 8) {
            emon.Port.CellsPush(assets, 0);
            i += 1;
        }
        emon.Port.CellsPush(assets, w);
        emon.Port.CellsPush(assets, h);
        emon.Port.CellsPush(assets, dpi);
        emon.Port.CellsPush(assets, flags);
        emon.Port.CellsPush(assets, -1);
        emon.Port.CellsPush(assets, 0);
        emon.Port.CellsPush(assets, -1);
        emon.Port.CellsPush(assets, 0);
        emon.Port.CellsPush(assets, 0);
        emon.Port.CellsPush(assets, 0);
        return id;
    }
